t = ?
[A]_{t} = [B]_{t}
[A]_{0} e^{-k_{A} \times t} = [B]_{0} e^{-k_{B} \times t}
\Rightarrow \frac{[A]_{0}}{[B]_{0}} = e^{(k_{A} - k_{B})t}
\Rightarrow 8 = e^{(k_{A} - k_{B}) \times t}
\Rightarrow \ln 8 = (k_{A} - k_{B}) \times t
\Rightarrow \ln 8 = \ln 2 \left(\frac{1}{(t_{1/2})_{A}} - \frac{1}{(t_{1/2})_{B}}\right) \times t
\Rightarrow 3 \ln 2 = \ln 2 \left(\frac{1}{10} - \frac{1}{40}\right) \times t
\Rightarrow 3 = \left(\frac{4-1}{40}\right) \times t
\Rightarrow 3 = \left(\frac{3}{40}\right) \times t
\Rightarrow t = 40 \text{ min}

